<script setup>
import { computed, onMounted, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { AlertTriangle, CheckCircle2, ClipboardList, PackageSearch, RefreshCw, Truck, Users, Warehouse } from 'lucide-vue-next';
import { axios } from '../../lib/echo';

const route = useRoute();
const router = useRouter();
const activeTab = ref('overview');
const activeMode = ref('bulk');
const loading = ref(false);
const error = ref('');
const notice = ref('');
const orders = ref([]);
const riders = ref([]);
const pickups = ref([]);
const hubs = ref([]);
const search = ref('');
const statusFilter = ref('');
const selectedIds = ref([]);
const selectedRider = ref('');
const receivingHubId = ref('');
const expectedCount = ref('');
const busy = ref(false);

const tabs = [{ id: 'overview', label: 'Overview' }, { id: 'pickups', label: 'Pickups' }, { id: 'riders', label: 'Riders' }, { id: 'exceptions', label: 'Exceptions' }, { id: 'hubs', label: 'Hubs' }];
const statuses = ['received', 'in_transit', 'in_hub', 'assigned_to_rider', 'out_for_delivery', 'delivered', 'in_return_queue'];
const label = (value) => String(value || '').replaceAll('_', ' ');
const modeOrders = computed(() => activeMode.value === 'assign' ? orders.value.filter((order) => ['received', 'in_hub'].includes(order.status) && !order.rider_id) : activeMode.value === 'monitor' ? orders.value.filter((order) => ['assigned_to_rider', 'in_hub', 'out_for_delivery', 'delivered', 'in_return_queue'].includes(order.status) || order.rider_id) : orders.value);
const filteredOrders = computed(() => modeOrders.value.filter((order) => { const query = search.value.toLowerCase().trim(); const haystack = [order.awb_number, order.recipient_name, order.recipient_address].filter(Boolean).join(' ').toLowerCase(); return (!query || haystack.includes(query)) && (!statusFilter.value || order.status === statusFilter.value); }));
const metrics = computed(() => ({ ready: orders.value.filter((order) => ['in_hub', 'received'].includes(order.status)).length, assigned: orders.value.filter((order) => order.rider_id).length, active: orders.value.filter((order) => order.status === 'out_for_delivery').length, failed: orders.value.filter((order) => ['in_return_queue', 'failed'].includes(order.status) || order.delivery_status === 'failed').length }));
const syncRoute = () => { activeTab.value = tabs.some((tab) => tab.id === route.params.tab) ? route.params.tab : tabs.some((tab) => tab.id === route.query.tab) ? route.query.tab : 'overview'; activeMode.value = ['assign', 'monitor'].includes(route.query.mode) ? route.query.mode : 'bulk'; };
const goTab = (tab, mode = activeMode.value) => router.push({ name: 'CourierAdminTab', params: { tab }, query: tab === 'overview' && mode !== 'bulk' ? { mode } : {} });
const load = async () => { loading.value = true; error.value = ''; try { const [ordersResponse, ridersResponse, pickupsResponse, hubsResponse] = await Promise.all([axios.get('/orders', { params: { per_page: 100 } }), axios.get('/riders', { params: { per_page: 100, application_status: 'approved' } }), axios.get('/pickup-requests', { params: { per_page: 100 } }), axios.get('/hubs')]); orders.value = ordersResponse.data.data || []; riders.value = ridersResponse.data.data || []; pickups.value = pickupsResponse.data.data || []; hubs.value = hubsResponse.data || []; } catch (requestError) { error.value = requestError.response?.data?.message || 'Unable to load courier operations.'; } finally { loading.value = false; } };
const toggleOrder = (id) => { selectedIds.value = selectedIds.value.includes(id) ? selectedIds.value.filter((item) => item !== id) : [...selectedIds.value, id]; };
const selectVisible = () => { selectedIds.value = selectedIds.value.length === filteredOrders.value.length ? [] : filteredOrders.value.map((order) => order.id); };
const assignSelected = async () => { if (!selectedIds.value.length || !selectedRider.value) return; busy.value = true; try { await axios.post('/riders/assign-orders', { rider_id: selectedRider.value, order_ids: selectedIds.value }); notice.value = `${selectedIds.value.length} parcel(s) assigned to the rider.`; selectedIds.value = []; selectedRider.value = ''; await load(); } catch (requestError) { error.value = requestError.response?.data?.message || 'Unable to assign parcels.'; } finally { busy.value = false; } };
const receiveBulk = async () => { if (!selectedIds.value.length || !receivingHubId.value || !expectedCount.value) return; busy.value = true; try { const response = await axios.post('/orders/receive-bulk', { order_ids: selectedIds.value, hub_id: receivingHubId.value, expected_count: Number(expectedCount.value) }); notice.value = `${response.data.received_count} parcel(s) received.`; selectedIds.value = []; await load(); } catch (requestError) { error.value = requestError.response?.data?.message || 'Unable to receive bulk shipment.'; } finally { busy.value = false; } };
const updateStatus = async (order, nextStatus) => { busy.value = true; try { await axios.patch(`/orders/${order.id}/operational-status`, { status: nextStatus }); notice.value = `${order.awb_number} updated.`; await load(); } catch (requestError) { error.value = requestError.response?.data?.message || 'Unable to update parcel status.'; } finally { busy.value = false; } };
watch(() => [route.params.tab, route.query.tab, route.query.mode], syncRoute, { immediate: true });
onMounted(load);
</script>

<template>
  <main class="min-h-screen bg-[#f4f7f6] px-4 py-6 text-slate-900 sm:px-6 lg:px-8"><div class="mx-auto max-w-7xl">
    <header class="flex flex-wrap items-end justify-between gap-5 border-b border-slate-200 pb-6"><div><p class="text-xs font-black uppercase tracking-[0.24em] text-blue-700">Courier administration</p><h1 class="mt-2 text-3xl font-black tracking-tight">{{ activeTab === 'overview' ? ({ bulk: 'Bulk received', assign: 'Sort and assign', monitor: 'Delivery monitor' }[activeMode]) : tabs.find((tab) => tab.id === activeTab)?.label }}</h1><p class="mt-2 text-sm text-slate-500">Operate the courier queue from one workspace.</p></div><button class="inline-flex items-center gap-2 bg-slate-950 px-4 py-2.5 text-sm font-bold text-white hover:bg-blue-700" @click="load"><RefreshCw class="h-4 w-4" :class="loading ? 'animate-spin' : ''" />Refresh</button></header>
    <section class="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><article v-for="item in [{ label: 'Ready for assignment', value: metrics.ready, icon: PackageSearch }, { label: 'Assigned parcels', value: metrics.assigned, icon: Users }, { label: 'Out for delivery', value: metrics.active, icon: Truck }, { label: 'Exceptions / returns', value: metrics.failed, icon: AlertTriangle }]" :key="item.label" class="border border-slate-200 bg-white p-5 shadow-sm"><div class="flex items-start justify-between"><div><p class="text-sm font-semibold text-slate-500">{{ item.label }}</p><p class="mt-3 text-3xl font-black">{{ item.value }}</p></div><component :is="item.icon" class="h-5 w-5 text-blue-700" /></div></article></section>
    <nav class="mt-8 flex gap-1 overflow-x-auto border-b border-slate-200"><button v-for="tab in tabs" :key="tab.id" class="shrink-0 border-b-2 px-4 py-3 text-sm font-bold" :class="activeTab === tab.id ? 'border-blue-600 text-blue-700' : 'border-transparent text-slate-500'" @click="goTab(tab.id)">{{ tab.label }}</button></nav>
    <div v-if="notice" class="mt-5 flex items-center gap-2 border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-bold text-emerald-800"><CheckCircle2 class="h-4 w-4" />{{ notice }}</div><div v-if="error" class="mt-5 border border-rose-200 bg-rose-50 px-4 py-3 text-sm font-bold text-rose-800">{{ error }}</div>
    <section v-if="activeTab === 'overview'" class="mt-5"><div class="flex gap-2"><button v-for="mode in [{ id: 'bulk', label: 'Bulk received' }, { id: 'assign', label: 'Sort & assign' }, { id: 'monitor', label: 'Delivery monitor' }]" :key="mode.id" class="border px-3 py-2 text-sm font-bold" :class="activeMode === mode.id ? 'border-blue-600 text-blue-700' : 'border-slate-200 text-slate-500'" @click="goTab('overview', mode.id)">{{ mode.label }}</button></div><section class="mt-4 overflow-hidden border border-slate-200 bg-white shadow-sm"><header class="grid gap-3 border-b border-slate-200 bg-slate-50 p-4 md:grid-cols-[1.5fr_1fr]"><input v-model="search" class="border border-slate-300 bg-white px-3 py-2 text-sm" placeholder="Search tracking number or recipient" /><select v-model="statusFilter" class="border border-slate-300 bg-white px-3 py-2 text-sm"><option value="">All parcel statuses</option><option v-for="status in statuses" :key="status" :value="status">{{ label(status) }}</option></select></header><div class="overflow-x-auto"><table class="w-full min-w-[900px] text-left text-sm"><thead class="bg-slate-50 text-[11px] font-black uppercase tracking-wider text-slate-500"><tr><th class="px-5 py-3"><input type="checkbox" :checked="filteredOrders.length > 0 && selectedIds.length === filteredOrders.length" @change="selectVisible" /></th><th class="px-5 py-3">Parcel</th><th class="px-5 py-3">Hub</th><th class="px-5 py-3">Status</th><th class="px-5 py-3">Action</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="order in filteredOrders" :key="order.id"><td class="px-5 py-4"><input type="checkbox" :checked="selectedIds.includes(order.id)" @change="toggleOrder(order.id)" /></td><td class="px-5 py-4"><p class="font-mono font-black text-blue-700">{{ order.awb_number }}</p><p class="mt-1 text-xs text-slate-500">{{ order.recipient_name }}</p></td><td class="px-5 py-4 text-xs font-bold"><Warehouse class="mr-1 inline h-3.5 w-3.5 text-teal-700" />{{ order.current_hub?.name || order.hub?.name || 'Unassigned' }}</td><td class="px-5 py-4"><span class="bg-slate-100 px-2 py-1 text-[11px] font-black capitalize">{{ label(order.status) }}</span></td><td class="px-5 py-4"><select class="border border-slate-300 bg-white px-2 py-1 text-xs" :value="order.status" @change="updateStatus(order, $event.target.value)"><option v-for="status in statuses" :key="status" :value="status">{{ label(status) }}</option></select></td></tr></tbody></table><p v-if="!filteredOrders.length" class="p-10 text-center text-sm text-slate-500">No parcels match this view.</p></div></section><section v-if="activeMode === 'bulk'" class="mt-4 flex flex-wrap items-end gap-3 border border-blue-100 bg-blue-50 p-4"><label class="text-xs font-black uppercase text-blue-800">Receiving hub<select v-model="receivingHubId" class="mt-2 block border border-blue-200 bg-white px-3 py-2 text-sm"><option value="">Select hub</option><option v-for="hub in hubs" :key="hub.id" :value="hub.id">{{ hub.name }}</option></select></label><label class="text-xs font-black uppercase text-blue-800">Expected count<input v-model="expectedCount" type="number" min="1" class="mt-2 block border border-blue-200 bg-white px-3 py-2 text-sm" /></label><button class="bg-blue-700 px-4 py-2 text-sm font-bold text-white disabled:opacity-40" :disabled="busy || !selectedIds.length || !receivingHubId || !expectedCount" @click="receiveBulk"><ClipboardList class="mr-1 inline h-4 w-4" />Receive bulk</button></section><section v-if="activeMode === 'assign'" class="mt-4 flex items-end gap-3 border border-teal-100 bg-teal-50 p-4"><label class="text-xs font-black uppercase text-teal-800">Assign rider<select v-model="selectedRider" class="mt-2 block border border-teal-200 bg-white px-3 py-2 text-sm"><option value="">Select rider</option><option v-for="rider in riders" :key="rider.id" :value="rider.id">{{ rider.user?.name }}</option></select></label><button class="bg-teal-700 px-4 py-2 text-sm font-bold text-white disabled:opacity-40" :disabled="busy || !selectedIds.length || !selectedRider" @click="assignSelected">Assign selected</button></section></section>
    <section v-else-if="activeTab === 'pickups'" class="mt-6 border border-slate-200 bg-white p-5"><h2 class="text-xl font-black">Pickup requests</h2><div class="mt-4 divide-y divide-slate-100"><article v-for="pickup in pickups" :key="pickup.id" class="flex justify-between gap-3 py-4"><div><p class="font-mono text-xs font-black text-teal-700">{{ pickup.request_code }}</p><p class="mt-1 font-bold">{{ pickup.contact_person }}</p></div><span class="text-xs font-black capitalize">{{ label(pickup.status) }}</span></article><p v-if="!pickups.length" class="p-8 text-center text-sm text-slate-500">No pickup requests.</p></div></section>
    <section v-else-if="activeTab === 'riders'" class="mt-6 border border-slate-200 bg-white p-5"><h2 class="text-xl font-black">Courier riders</h2><div class="mt-4 grid gap-3 md:grid-cols-2"><article v-for="rider in riders" :key="rider.id" class="border border-slate-200 p-4"><p class="font-black">{{ rider.user?.name }}</p><p class="mt-1 text-xs text-slate-500">{{ rider.user?.email }}</p><p class="mt-3 text-xs text-slate-600">{{ rider.hub?.name || 'No hub' }} · {{ rider.vehicle_type }}</p></article></div></section>
    <section v-else-if="activeTab === 'exceptions'" class="mt-6 border border-rose-200 bg-white p-5"><h2 class="text-xl font-black">Exceptions and returns</h2><p class="mt-4 text-sm text-slate-500">{{ metrics.failed }} parcel(s) require review.</p></section>
    <section v-else class="mt-6 border border-slate-200 bg-white p-5"><h2 class="text-xl font-black">Registered hubs</h2><div class="mt-4 grid gap-3 md:grid-cols-3"><article v-for="hub in hubs" :key="hub.id" class="border border-slate-200 p-4"><p class="font-black">{{ hub.name }}</p><p class="mt-1 text-xs text-slate-500">{{ hub.code }}</p></article></div></section>
  </div></main>
</template>